from pathlib import Path
import html
root=Path('artifacts/world-life')
scenes=[('station','A friendly stop','Station dogs sniff, wander and wag their tails. Their neighbors wave as you approach.'),('gulls','Company above the coast','Small gull flocks flap, bank and climb when a car passes nearby.'),('beach','An afternoon by the sea','Visitors fly bright kites with moving fabric tails and wind-tugged lines.'),('redwoods','Eyes among the redwoods','Deer graze in small family groups, then look up when you pass or sound the horn.'),('cyclist','Taking the long way','Touring cyclists pedal along the separate roadside path.'),('lodge','A moment worth keeping','Lodge visitors carry cameras, take occasional pictures and greet passing drivers.'),('headlands','One more stop','Different dog coats and coordinated collars give the four stations their own residents.'),('sunset-kites','Stay for the view','Picnic baskets, coffee cups and colorful kites bring the overlooks to life.')]
models=[('dog','Station retriever'),('gull','Pacific gull'),('deer','Redwood deer'),('visitor','Coastal visitor'),('cyclist','Touring cyclist'),('kite','Beach kite'),('picnic','Picnic basket & coffee')]
cards=''.join(f'<a class="card" href="{key}.png"><img src="{key}.png" alt="{html.escape(title)}" loading="lazy"><div><h3>{title}</h3><p>{description}</p></div></a>' for key,title,description in scenes)
studies=''.join(f'<a class="card" href="model-{key}.png"><img src="model-{key}.png" alt="{html.escape(title)} model study" loading="lazy"><div><h3>{title}</h3></div></a>' for key,title in models)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pacific Run · life along the coast</title><style>
*{box-sizing:border-box}body{margin:0;background:#122124;color:#eee9d6;font:16px/1.6 system-ui}main{max-width:1360px;margin:auto;padding:46px 30px 60px}small{color:#d9b578;text-transform:uppercase;letter-spacing:.18em;font-size:12px}h1{font:500 clamp(34px,5vw,58px)/1.12 Georgia;margin:10px 0 18px;max-width:790px}h2{font-weight:500;margin:46px 0 12px}h3{font-size:19px;font-weight:500;margin:0 0 8px}p{color:#acbeb7;max-width:800px}nav{display:flex;gap:26px;flex-wrap:wrap;margin:24px 0 30px}a{color:#e2c08b}a:focus-visible{outline:2px solid #f2d097;outline-offset:4px}video{display:block;width:100%;aspect-ratio:1.6;background:#17262b;border:1px solid #3b4d4b;border-radius:8px}.hint{padding:13px 18px;border-left:2px solid #c3a365;background:#1b2e31;color:#d7dbc8}kbd{background:#30423f;color:#f1dca9;padding:2px 7px;border-radius:3px;font:inherit;font-size:14px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:26px}.studies{grid-template-columns:repeat(3,minmax(0,1fr))}.card{display:block;color:inherit;text-decoration:none;background:#1d3033;border:1px solid #384a48;border-radius:8px;overflow:hidden}.card img{display:block;width:100%;aspect-ratio:1.6;object-fit:cover}.card div{padding:16px 19px}.card p{font-size:14px;margin:0}.studies img{aspect-ratio:1.55}.studies h3{font-size:17px;margin:0}.note{font-size:13px;margin:10px 0 0}@media(max-width:800px){.studies{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:30px 18px}}@media(max-width:550px){.grid{grid-template-columns:1fr}nav{gap:17px}}
</style><main><small>Pacific Run · the living coast</small><h1>There is more to see along the way.</h1><p>A curious dog beside the station. A gull banking overhead. A kite tugging in the ocean breeze. Small scenes unfold at different times along all three regions, and the neighbors notice your car.</p><nav><a href="/">Go for a drive →</a><a href="/artifacts/water/water-gallery.html">Explore the water →</a><a href="/artifacts/juice/detail-gallery.html">Vehicle collection →</a><a href="/artifacts/road-land/road-gallery.html">Road & land →</a><a href="#characters">Meet the characters ↓</a></nav><video controls playsinline muted loop preload="metadata" poster="motion-dog.png" aria-label="In-engine showcase of animated coastal wildlife and visitors"><source src="world-life.webm" type="video/webm"><source src="world-life.mp4" type="video/mp4"></video><p class="note">A short showcase captured in the game renderer.</p><p class="hint">Say hello with <kbd>H</kbd>, <kbd>Gamepad X</kbd>, or the on-screen <kbd>HORN</kbd> button. Nearby people and wildlife respond.</p><h2>Little stories along the road</h2><div class="grid">'''+cards+'''</div><h2 id="characters">Meet the coast</h2><p>Seven original Blender assets, with independent moving parts, detailed clothing and accessories, feather layers, bicycle running gear, and picnic props.</p><div class="grid studies">'''+studies+'''</div></main></html>'''
(root/'world-gallery.html').write_text(page,encoding='utf8')
